51	class UriPartsDialog extends AModuleDialog {
52	
53	    private LinearLayout box;
54	    private final List<String> expandedGroups = new ArrayList<>();
55	
56	    public UriPartsDialog(MainDialog dialog) {
57	        super(dialog);
58	    }
59	
60	    @Override
61	    public int getLayoutId() {
62	        return R.layout.dialog_parts;
63	    }
