70	    @Override
71	    public void onDisplayUrl(UrlData urlData) {
72	        // clear
73	        box.removeAllViews();
74	
75	        // parse
76	        var uri = Uri.parse(urlData.url);
77	        var urlQuerySanitizer = new UrlQuerySanitizer();
78	        // the default parseUrl doesn't remove the fragment
79	        if (uri.getQuery() != null) {
80	            urlQuerySanitizer.setAllowUnregisteredParamaters(true);
81	            urlQuerySanitizer.setUnregisteredParameterValueSanitizer(v -> v);
82	            urlQuerySanitizer.parseQuery(uri.getQuery());
83	        }
84	
85	        // domain elements
86	        if (uri.getAuthority() != null || uri.getScheme() != null) {
87	            var domain = addGroup("Domain", -1, null);
88	            addPart("scheme", uri.getScheme(), domain, null);
89	            addPart("user info", uri.getUserInfo(), domain, null);
90	            addPart("host", uri.getHost(), domain, null);
91	            addPart("port", uri.getPort() != -1 ? String.valueOf(uri.getPort()) : null, domain, null);
92	        }
93	
94	        // paths
95	        var pathSegments = uri.getPathSegments();
96	        if (pathSegments.size() > 0) {
97	            var paths = addGroup("Paths", pathSegments.size(), uri.buildUpon().path(null));
98	            for (var i = 0; i < pathSegments.size(); i++) {
99	                var pathSegment = pathSegments.get(i);
100	
101	                var builder = uri.buildUpon();
102	                builder.path(null);
103	                for (int newI = 0; newI < pathSegments.size(); newI++) {
104	                    if (newI != i) builder.appendPath(pathSegments.get(newI));
105	                }
106	                addPart("/", pathSegment, paths, builder);
107	            }
108	        }
109	
110	        // query parameters
111	        var parameters = urlQuerySanitizer.getParameterList();
112	        if (parameters.size() > 0) {
113	            var queries = addGroup("Parameters", parameters.size(), uri.buildUpon().query(null));
114	            for (var i = 0; i < parameters.size(); i++) {
115	                // generate same url but without this parameter
116	                var builder = uri.buildUpon();
117	                builder.query(null);
118	                for (var j = 0; j < parameters.size(); j++) {
119	                    if (i != j) builder.appendQueryParameter(parameters.get(j).mParameter, parameters.get(j).mValue);
120	                }
121	                // append the parameter
122	                addPart(parameters.get(i).mParameter, parameters.get(i).mValue, queries, builder);
123	            }
124	        }
125	
126	        // fragment
127	        if (uri.getFragment() != null) {
128	            var fragment = addGroup("Fragment", -1, uri.buildUpon().fragment(null));
129	            addPart("#", uri.getFragment(), fragment, null);
130	        }
131	
132	        setVisibility(box.getChildCount() > 0);
133	    }
