138	    private LinearLayout addGroup(String name, int size, Uri.Builder onDelete) {
139	        var title = Inflater.inflate(R.layout.uri_part, box);
140	        title.findViewById(R.id.key).setVisibility(View.GONE);
141	
142	        var name_view = title.<TextView>findViewById(R.id.value);
143	        name_view.setText(name + (size <= -1 ? "" : " (" + size + ")"));
144	        AndroidUtils.setAsClickable(name_view);
145	
146	        var delete_view = title.<Button>findViewById(R.id.delete);
147	        if (onDelete == null) delete_view.setVisibility(View.GONE);
148	        else delete_view.setOnClickListener(v -> setUrl(onDelete.build().toString()));
149	
150	        var group = Inflater.<LinearLayout>inflate(R.layout.dialog_parts, box);
151	        group.setVisibility(expandedGroups.contains(name) ? View.VISIBLE : View.GONE);
152	        AndroidUtils.toggleableListener(
153	                title,
154	                v -> JavaUtils.toggleContains(expandedGroups, name),
155	                v -> {
156	                    group.setVisibility(expandedGroups.contains(name) ? View.VISIBLE : View.GONE);
157	                    name_view.setCompoundDrawablesRelativeWithIntrinsicBounds(expandedGroups.contains(name) ? R.drawable.arrow_down : R.drawable.arrow_right, 0, 0, 0);
158	                }
159	        );
160	
161	        return group;
162	    }
