172	        // configure key
173	        var key_view = part.<TextView>findViewById(R.id.key);
174	        key_view.setText(name.isEmpty() ? getActivity().getString(R.string.mParts_empty) : name);
175	        if (!name.isEmpty()) key_view.setOnLongClickListener(longTapToCopy);
176	
177	        // configure value
178	        var value_view = part.<TextView>findViewById(R.id.value);
179	        value_view.setText(value);
180	        AndroidUtils.setAsClickable(value_view);
181	        value_view.setOnClickListener(v -> setUrl(value));
182	        value_view.setOnLongClickListener(longTapToCopy);
183	
184	        // configure delete
185	        var delete_view = part.<Button>findViewById(R.id.delete);
186	        if (onDelete != null) {
187	            try {
188	                var newUrl = onDelete.build().toString();
189	                delete_view.setOnClickListener(v -> setUrl(newUrl));
190	            } catch (UnsupportedOperationException ignored) {
191	                delete_view.setVisibility(View.GONE);
192	            }
193	        } else {
194	            delete_view.setVisibility(View.GONE);
195	        }
196	    }
