151	    /**
152	     * Manages the splitting, removing and merging of queries
153	     */
154	    private static class UrlParts {
155	        private final String preQuery; // "http://google.com"
156	        private final List<String> queries = new ArrayList<>(); // ["ref=foo","bar"]
157	        private final String postQuery; // "#start"
158	
159	        /**
160	         * Prepares a url and extracts its queries
161	         */
162	        public UrlParts(String url) {
163	            // an uri is defined as [scheme:][//authority][path][?query][#fragment]
164	            // we need to find a '?' followed by anything except a '#'
165	            // this allows us to work with any string, even with non-standard or malformed uris
166	            int iStart = url.indexOf("?"); // position of '?' (-1 if not present)
167	            int iEnd = url.indexOf("#", iStart + 1);
168	            iEnd = iEnd == -1 ? url.length() : iEnd; // position of '#' (end of string if not present)
169	
170	            // add part until '?' or until postQuery if not present
171	            preQuery = url.substring(0, iStart != -1 ? iStart : iEnd);
172	            // add queries if any
173	            if (iStart != -1) {
174	                queries.addAll(splitFix(url.substring(iStart + 1, iEnd), "&"));
175	            }
176	            // add part after queries (empty if not present)
177	            postQuery = url.substring(iEnd);
178	        }
179	
180	        /**
181	         * returns the number of queries present
182	         */
183	        public int queriesSize() {
184	            return queries.size();
185	        }
186	
187	        /**
188	         * Returns the name of a query (by index)
189	         */
190	        public String getQueryName(int index) {
191	            return queries.get(index).split("=")[0];
192	        }
193	
194	        /**
195	         * Returns the decoded value of a query (by index)
196	         */
197	        public String getQueryValue(int index) {
198	            String[] split = queries.get(index).split("=");
199	            if (split.length == 1) return "";
200	            try {
201	                return URLDecoder.decode(split[1]);
202	            } catch (Exception e) {
203	                // can't decode, return it directly
204	                return split[1];
205	            }
206	        }
207	
208	        /**
209	         * Returns the full url
210	         */
211	        public String getUrl() {
212	            return getUrlWithoutQuery(-1);
213	        }
214	
215	        /**
216	         * Returns the url without one query (by index)
217	         */
218	        public String getUrlWithoutQuery(int index) {
219	            var sb = new StringBuilder();
220	
221	            // concatenate queries
222	            for (int i = 0; i < queries.size(); ++i)
223	                // excluding the required one
224	                if (i != index)
225	                    // first after '?', the rest after '&'
226	                    sb.append(sb.length() == 0 ? "?" : "&").append(queries.get(i));
227	
228	            // finish building
229	            sb.insert(0, preQuery);
230	            sb.append(postQuery);
231	            return sb.toString();
232	        }
233	
234	        /**
235	         * Returns the url without queries
236	         */
237	        public String getUrlWithoutQueries() {
238	            return preQuery + postQuery;
239	        }
240	    }
241	
242	    /**
243	     * {@link String#split(String)} won't return the last element if it's empty.
244	     * This function does. And it returns a list instead of an array.
245	     * Everything else is the same.
246	     * Note: regex must not match '#', it does change this function
247	     */
248	    private static List<String> splitFix(String string, String regex) {
249	        // split with an extra char
250	        String[] parts = (string + "#").split(regex);
251	        // remove the extra char
252	        parts[parts.length - 1] = parts[parts.length - 1].substring(0, parts[parts.length - 1].length() - 1);
253	        return Arrays.asList(parts);
254	    }
255	}
