/**
 * Splits an encoded query (the part between '?' and '#') into its parameters,
 * without decoding them, so that their original encoding is preserved
 */
private static List<String> splitEncodedQuery(String encodedQuery) {
    if (encodedQuery == null || encodedQuery.isEmpty()) return Collections.emptyList();
    var parameters = new ArrayList<String>();
    var start = 0;
    while (start <= encodedQuery.length()) {
        var end = encodedQuery.indexOf('&', start);
        if (end == -1) end = encodedQuery.length();
        // skip empty parameters (e.g. "?foo=bar&&baz")
        if (end > start) parameters.add(encodedQuery.substring(start, end));
        start = end + 1;
    }
    return parameters;
}

