 * Note: unlike {@link android.net.UrlQuerySanitizer}, multibyte (non-ascii) characters are
 * decoded correctly, and unlike {@link Uri#decode(String)}, invalid escapes are kept as-is
 * instead of being replaced by a replacement character
 */
private static String decode(String encoded) {
    if (encoded.indexOf('%') == -1 && encoded.indexOf('+') == -1) return encoded;
    try {
        return URLDecoder.decode(encoded, "UTF-8");
    } catch (Exception e) {
        // can't decode (e.g. invalid escape sequence), show it as-is
        return encoded;
    }
}

