/**
 * Splits the encoded query of an uri (the part between '?' and '#') into its decoded
 * parameters, each one as a {name, value} pair (the value is empty if there is no '=')
 */
private static List<String[]> splitEncodedQuery(String encodedQuery) {
    if (encodedQuery == null || encodedQuery.isEmpty()) return Collections.emptyList();
    var parameters = new ArrayList<String[]>();
    var start = 0;
    while (start <= encodedQuery.length()) {
        var end = encodedQuery.indexOf('&', start);
        if (end == -1) end = encodedQuery.length();
        // skip empty parameters (e.g. "?foo=bar&&baz")
        if (end > start) {
            var parameter = encodedQuery.substring(start, end);
            // only the first '=' separates the name from the value
            var iEquals = parameter.indexOf('=');
            parameters.add(new String[]{
                    decode(iEquals == -1 ? parameter : parameter.substring(0, iEquals)),
                    decode(iEquals == -1 ? "" : parameter.substring(iEquals + 1))
            });
        }
        start = end + 1;
    }
    return parameters;
}

/**
 * Decodes a percent-encoded text, as utf-8 (so multibyte characters are decoded correctly,
 * unlike {@link android.net.UrlQuerySanitizer}, which decodes each escape as a single char).
 * Repeats while it keeps decoding (e.g. "%25E6%259D%25A5" is encoded twice), and returns the
 * last successfully decoded text, so invalid escapes are shown as-is instead of failing or
 * being replaced by a replacement character (as {@link Uri#decode(String)} does).
 */
private static String decode(String encoded) {
    var decoded = encoded;
    // note: decoding always shortens the text, so this always ends
    while (decoded.indexOf('%') != -1 || decoded.indexOf('+') != -1) {
        String result;
        try {
            result = URLDecoder.decode(decoded, "UTF-8");
        } catch (Exception e) {
            // can't be decoded (e.g. invalid escape sequence), keep the last valid one
            break;
        }
        if (result.equals(decoded)) break;
        decoded = result;
    }
    return decoded;
}

