242	    /**
243	     * {@link String#split(String)} won't return the last element if it's empty.
244	     * This function does. And it returns a list instead of an array.
245	     * Everything else is the same.
246	     * Note: regex must not match '#', it does change this function
247	     */
248	    private static List<String> splitFix(String string, String regex) {
249	        // split with an extra char
250	        String[] parts = (string + "#").split(regex);
251	        // remove the extra char
252	        parts[parts.length - 1] = parts[parts.length - 1].substring(0, parts[parts.length - 1].length() - 1);
253	        return Arrays.asList(parts);
254	    }
