116	    /**
117	     * Copy to the clipboard
118	     */
119	    static void copyToClipboard(Activity activity, String toast, String text) {
120	        ClipboardManager clipboard = (ClipboardManager) activity.getSystemService(Context.CLIPBOARD_SERVICE);
121	        if (clipboard == null) return;
122	
123	        clipboard.setPrimaryClip(ClipData.newPlainText("", text));
124	
125	        // show toast to notify it was copied (except on Android 13+, where the device shows a popup itself)
126	        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU)
127	            Toast.makeText(activity, toast, Toast.LENGTH_LONG).show();
