130	    /**
131	     * Get the (possible) referrer activity from an existing one.
132	     * Null if can't find
133	     */
134	    static String getReferrer(Activity activity) {
135	        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.LOLLIPOP_MR1) return null;
136	
137	        Uri referrer = activity.getReferrer();
138	        if (referrer == null) return null;
139	
140	        // the scheme must be "android-app"
141	        if (!"android-app".equals(referrer.getScheme())) return null;
142	        // the host is the package
143	        return referrer.getHost();
