155	    /**
156	     * Sets an onClickListener to a [view] so that:
157	     * [toggle] will be called when clicked (to change something).
158	     * [listener] will be called now and when clicked (to update state).
159	     * If you need to initialize things, do them before calling this.
160	     */
161	    static <V extends View> void toggleableListener(V view, JavaUtils.Consumer<V> toggle, JavaUtils.Consumer<V> listener) {
162	        view.setOnClickListener(v -> {
163	            toggle.accept(view);
164	            listener.accept(view);
165	        });
166	        listener.accept(view);
167	    }
