169	    /**
170	     * Adds an onLongClickListener that will show a toast with the contentdescription
171	     */
172	    static void longTapForDescription(View view) {
173	        view.setOnLongClickListener(v -> {
174	            var contentDescription = v.getContentDescription();
175	            if (contentDescription == null) AndroidUtils.assertError("No content description for view " + view);
176	            Toast.makeText(v.getContext(), contentDescription, Toast.LENGTH_SHORT).show();
177	            return true;
