189	    /**
190	     * Fixes the color of a MenuItem icon (colorFilter=textColorPrimary)
191	     */
192	    static void fixMenuIconColor(MenuItem menuItem, Context cntx) {
193	        // get color
194	        var resolvedAttr = new TypedValue();
195	        cntx.getTheme().resolveAttribute(android.R.attr.textColorPrimary, resolvedAttr, true);
196	
197	        // tint
198	        menuItem.getIcon().setColorFilter(cntx.getResources().getColor(resolvedAttr.resourceId), PorterDuff.Mode.SRC_IN);
199	    }
200	
201	    /**
202	     * Returns all the unique links found on a given text
203	     */
204	    static Set<String> getLinksFromText(CharSequence text) {
205	        var links = new HashSet<String>();
206	        var matcher = Patterns.WEB_URL.matcher(text);
207	        while (matcher.find()) links.add(matcher.group());
208	        return links;
209	    }
