2	
3	import org.json.JSONException;
4	import org.json.JSONObject;
5	
6	import java.util.ArrayList;
7	import java.util.Collection;
8	import java.util.Iterator;
9	import java.util.List;
10	
11	/**
12	 * Generic Java utils.
13	 * I prefer smaller and more available apps, even if they require an older API and not using Kotlin
14	 */
15	public interface JavaUtils {
16	
17	    /**
18	     * Converts an iterator to a list
19	     */
20	    static <T> List<T> toList(Iterator<T> iterator) {
21	        List<T> list = new ArrayList<>();
22	        while (iterator.hasNext()) {
23	            list.add(iterator.next());
24	        }
25	        return list;
26	    }
27	
28	    /**
29	     * Converts a string into a json object, returns empty on failure
30	     */
31	    static JSONObject toJson(String content) {
32	        try {
33	            return new JSONObject(content);
34	        } catch (JSONException e) {
35	            // invalid catalog, return empty
36	            return new JSONObject();
37	        }
38	    }
39	
40	    /**
41	     * Clamps a value between two other values.
42	     */
43	    static int clamp(int min, int value, int max) {
44	        return min <= max ? Math.max(min, Math.min(value, max))
45	                // just in case
46	                : clamp(max, value, min);
47	    }
48	
49	    /**
50	     * Applies a filter to both strings to check if all words of keywords are in body.
51	     * The order does not matter.
52	     */
53	    static boolean containsWords(String body, String keywords) {
54	        JavaUtils.Function<String, String> filter = s -> s.toUpperCase().replaceAll("[\\s-_]+", " ");
55	        // Match all words
56	        String[] words = filter.apply(keywords).split(" ");
57	        body = filter.apply(body);
58	        boolean match = true;
59	        for (String str : words) {
60	            if (!body.contains(str)) {
61	                match = false;
62	                break;
63	            }
64	        }
65	        return match;
66	    }
67	
68	    /**
69	     * Takes the [limit] last lines of a [text], separated by [delimiter].
70	     * This is equivalent to text.split(delimiter).takeLast(limit).join(delimiter) but using java sdk 14 (and hopefully more efficient)
71	     */
72	    static String limitLines(String text, char delimiter, int limit) {
73	        // early exit
74	        if (limit <= 0 || text.isEmpty()) return "";
75	
76	        // find the first character of the last (first) line required
77	        var i = text.length() - 1; // character pointer
78	        var lines = 0; // count full lines (delimiters encountered)
79	        while (i >= 0 && lines < limit) {
80	            if (text.charAt(i) == delimiter) lines++; // delimiter found
81	            i--; // continue
82	        }
83	        // split if necessary
84	        if (lines >= limit) text = text.substring(i + 2); // found the lines, split
85	        return text;
86	    }
87	
88	    /**
89	     * Same as Arrays.compare, which is not available in api < 33
90	     */
91	    static int compareArrays(int[] l, int[] r) {
92	        int i = 0;
93	        while (i < l.length && i < r.length) {
94	            if (l[i] != r[i]) return Integer.signum(r[i] - l[i]);
95	            i++;
96	        }
97	        return Integer.signum(r.length - l.length);
98	    }
99	
100	    /**
101	     * Returns the object, or default if null
102	     * java.util.Optional requires api 24
103	     */
104	    static <T> T valueOrDefault(T value, T defaultValue) {
105	        return value == null ? defaultValue : value;
106	    }
107	
108	    /**
109	     * if the element is present in the list, removes it
110	     * if not, adds it
111	     */
112	    static <E> void toggleContains(Collection<E> list, E element) {
113	        if (list.contains(element)) list.remove(element);
114	        else list.add(element);
115	    }
116	
117	    /**
118	     * java.util.function.Consumer requires api 24
119	     */
120	    @FunctionalInterface
121	    interface Consumer<T> {
122	        void accept(T t);
123	    }
124	
125	    /**
126	     * java.util.function.Function requires api 24
127	     */
128	    @FunctionalInterface
129	    interface Function<T, R> {
130	        R apply(T t);
131	    }
132	
133	    /** Negates a boolean Function */
134	    static <T> Function<T, Boolean> negate(Function<T, Boolean> function) {
135	        return t -> !function.apply(t);
136	    }
137	
138	    /**
139	     * java.util.function.UnaryOperator requires api 24
140	     */
141	    @FunctionalInterface
142	    interface UnaryOperator<T> extends Function<T, T> {
143	    }
144	}
