28	
29	    /**
30	     * If set, the module that triggers the update will be notified (all callbacks)
31	     */
32	    public boolean triggerOwn = true;
33	
34	    public UrlData dontTriggerOwn() {
35	        triggerOwn = false;
36	        return this;
37	    }
38	
39	    /**
40	     * If set, the url will not be changed (future setUrl calls will be ignored)
41	     */
