50	     * If set, this update is considered 'minor' and modules may decide to ignore or merge it with the previous one
51	     */
52	    public boolean minorUpdate = false;
53	
54	    public UrlData asMinorUpdate() {
55	        minorUpdate = true;
56	        return this;
57	    }
58	
59	    // ------------------- extra data -------------------
60	
61	    private final Map<String, String> extraData = new HashMap<>();
62	
63	    /**
64	     * saves a key-value data, will be kept with automatic updates (but not with manual ones)
65	     */
66	    public UrlData putData(String key, String value) {
