68	        return this;
69	    }
70	
71	    /**
72	     * gets a key-value data, those set on this update or previous automatic ones
73	     */
74	    public String getData(String key) {
75	        return extraData.get(key);
76	    }
77	
78	    /**
79	     * adds all data from the parameter into this object
80	     */
81	    public void mergeData(UrlData urlData) {
82	        extraData.putAll(urlData.extraData);
