177	    private void updateSpinner(String url) {
178	        packages = PackageUtils.getOtherPackages(UrlUtils.getViewIntent(url, null), getActivity());
179	
180	        // remove referrer
181	        if (noReferrerPref.get()) {
182	            packages.remove(AndroidUtils.getReferrer(getActivity()));
183	        }
184	
185	        // remove rejected if desired (and is not a non-view action, like share)
186	        // note: this will be called each time, so a rejected package will not be rejected again if the user changes the url and goes back. This is expected
187	        if (rejectedPref.get() && Intent.ACTION_VIEW.equals(getActivity().getIntent().getAction())) {
188	            packages.remove(rejectionDetector.getPrevious(url));
189	        }
190	
191	        // check no apps
192	        if (packages.isEmpty()) {
