204	        btn_open.setText(getActivity().getString(R.string.mOpen_with, PackageUtils.getPackageName(packages.get(0), getActivity())));
205	        AndroidUtils.setEnabled(openParent, true);
206	        btn_open.setEnabled(true);
207	        menu.clear();
208	        if (packages.size() == 1) {
209	            btn_openWith.setVisibility(View.GONE);
210	        } else {
211	            btn_openWith.setVisibility(View.VISIBLE);
212	            for (int i = 1; i < packages.size(); i++) {
