222	     * Open url in a specific app
223	     *
224	     * @param index index from the packages list of the app to use
225	     */
226	    private void openUrl(int index) {
227	        // get
228	        if (index < 0 || index >= packages.size()) return;
229	        var chosen = packages.get(index);
230	
231	        // update as preferred over the rest
232	        lastOpened.prefer(chosen, packages, getUrl());
233	
234	        // open
235	        var intent = new Intent(getActivity().getIntent());
236	        if (Intent.ACTION_VIEW.equals(intent.getAction())) {
237	            // preserve original VIEW intent
